import requests, numpy as np, pandas as pd, math, collections
from sklearn.linear_model import LogisticRegression
from sklearn.model_selection import cross_val_score, StratifiedKFold
import matplotlib.pyplot as plt

# ---- rebuild features (self-contained) ----
def stream(q, fields="accession,ft_signal,ft_transmem,sequence"):
    return requests.get(f"https://rest.uniprot.org/uniprotkb/stream?query={q}&fields={fields}&format=json",timeout=300).json()["results"]
sp_set=stream("(organism_id:9606)+AND+(reviewed:true)+AND+(ft_signal:*)")
sa_set=stream('(organism_id:9606)+AND+(reviewed:true)+AND+(ft_transmem:"Signal-anchor+for+type+II+membrane+protein")')
AAs="ACDEFGHIKLMNPQRSTVWY"; aidx={a:i for i,a in enumerate(AAs)}
exp=[]
for e in sp_set:
    sq=e["sequence"]["value"]
    for f in e.get("features",[]):
        if f["type"]=="Signal" and f["location"]["end"].get("value"):
            end=f["location"]["end"]["value"]
            if end>=13 and end+2<=len(sq) and "ECO:0000269" in {ev.get("evidenceCode") for ev in f.get("evidences",[])}:
                exp.append(sq[end-13:end+2])
bg=collections.Counter()
for e in sp_set: bg.update(e["sequence"]["value"])
t=sum(bg[a] for a in AAs); bg={a:bg[a]/t for a in AAs}
PWM=np.zeros((15,20))
for j in range(15):
    c=collections.Counter(s[j] for s in exp)
    for i,a in enumerate(AAs): PWM[j,i]=math.log(((c[a]+1.)/(len(exp)+20.))/bg[a])
def sc(s,cut):
    w=s[cut-13:cut+2]
    return None if (len(w)!=15 or any(a not in aidx for a in w)) else sum(PWM[j,aidx[w[j]]] for j in range(15))
def bestcut(s): 
    v=[(sc(s,c),c) for c in range(14,46) if sc(s,c) is not None]; return max(v)
kd={'A':1.8,'R':-4.5,'N':-3.5,'D':-3.5,'C':2.5,'Q':-3.5,'E':-3.5,'G':-0.4,'H':-3.2,'I':4.5,'L':3.8,
    'K':-3.9,'M':1.9,'F':2.8,'P':-1.6,'S':-0.8,'T':-0.7,'W':-0.9,'Y':-1.3,'V':4.2}
def hfeat(s,n=45,thr=1.0,win=7):
    ss=s[:n]; sm=[np.mean([kd.get(a,0) for a in ss[max(0,i-3):i+4]]) for i in range(len(ss))]
    b=c=0
    for v in sm: c=c+1 if v>thr else 0; b=max(b,c)
    return b,float(np.max(sm))
def feats(s):
    p,cut=bestcut(s); hl,hm=hfeat(s)
    return [p,hl,hm,sum(1 for a in s[:8] if a in "KR")-sum(1 for a in s[:8] if a in "DE")],cut

X=[];y=[];nm=[]
for e in sp_set:
    sq=e["sequence"]["value"]
    if len(sq)>60 and any(f["type"]=="Signal" and "ECO:0000269" in {ev.get("evidenceCode") for ev in f.get("evidences",[])} for f in e.get("features",[])):
        X.append(feats(sq)[0]); y.append(1); nm.append(e["primaryAccession"])
for e in sa_set:
    sq=e["sequence"]["value"]
    tms=[f for f in e.get("features",[]) if f["type"]=="Transmembrane" and "Signal-anchor" in f.get("description","")]
    if tms and len(sq)>60 and tms[0]["location"]["start"]["value"]<=15:
        X.append(feats(sq)[0]); y.append(0); nm.append(e["primaryAccession"])
X=np.array(X); y=np.array(y)
clf=LogisticRegression(max_iter=5000,class_weight="balanced").fit(X,y)
cv=cross_val_score(clf,X,y,cv=StratifiedKFold(5,shuffle=True,random_state=0),scoring="roc_auc")
print("training set: %d cleaved-SP (experimental) vs %d type II signal anchors (TM start<=15)"%(y.sum(),(1-y).sum()))
print("5-fold CV ROC-AUC = %.3f +/- %.3f"%(cv.mean(),cv.std()))
print("feature weights [PWM, hydrophobic-stretch length, max KD, n-region net charge] =",np.round(clf.coef_[0],3))

accs={"AADACL2":"Q6P093","AADAC":"P22760","NCEH1":"Q6PIU2","AADACL3":"Q5VUY0","AADACL4":"Q5VUY2"}
qs={s:requests.get(f"https://rest.uniprot.org/uniprotkb/{a}.fasta",timeout=60).text.split("\n",1)[1].replace("\n","") for s,a in accs.items()}
ctrl={"DPP4(type II, exp)":"P27487","ST6GAL1(type II, exp)":"P15907","ASGR1(type II, exp)":"P07306",
      "CES1(secreted/ER-lumen SP)":"P23141","ALB(secreted SP)":"P02768","PON1(secreted SP)":"P27169"}
for k,a in ctrl.items():
    qs[k]=requests.get(f"https://rest.uniprot.org/uniprotkb/{a}.fasta",timeout=60).text.split("\n",1)[1].replace("\n","")
print("\n%-28s %7s %6s %4s %4s %6s  %s"%("protein","P(SP)","PWM","cut","P1","hlen","n-term 1-25"))
res=[]
for k,s in qs.items():
    f,cut=feats(s); p=clf.predict_proba([f])[0,1]
    res.append(dict(protein=k,P_cleavedSP=p,PWM=f[0],cut=cut,P1=s[cut-1],hlen=f[1],nq=f[3],nterm=s[:25]))
    print("%-28s %7.3f %6.2f %4d %4s %6.0f  %s"%(k,p,f[0],cut,s[cut-1],f[1],s[:25]))
pd.DataFrame(res).to_csv("sp_vs_anchor_classifier.csv",index=False)

fig,ax=plt.subplots(figsize=(8.5,4.6))
order=sorted(res,key=lambda r:r["P_cleavedSP"])
cols=["#d1495b" if r["protein"] in accs else ("#3a7ca5" if "SP" in r["protein"] else "#8d6a9f") for r in order]
ax.barh([r["protein"] for r in order],[r["P_cleavedSP"] for r in order],color=cols)
ax.axvline(.5,color="k",ls="--",lw=1)
ax.set_xlabel("P(cleaved signal peptide)  [logistic model, 5-fold CV AUC %.2f]"%cv.mean())
ax.set_title("AADAC-family N-termini score as signal anchors, not cleaved signal peptides")
ax.text(.52,.3,"cleaved SP ->",fontsize=8); ax.text(.46,.3,"<- signal anchor",fontsize=8,ha="right")
plt.tight_layout(); plt.show()
